(* icon_names_gen — build-time generator for the native tabler icon
   name table.

   Reads assets/icon-names.json (the [display, kebab] pair list shipped
   to the web app as a lazy chunk via Icon_picker_names) and emits
   apple/icon_names_data.ml: the same table compiled into the native
   binary so the icon picker works without a runtime fetch. *)

let die fmt = Printf.ksprintf (fun s -> prerr_endline s; exit 1) fmt

let lit s =
  let b = Buffer.create (String.length s + 2) in
  Buffer.add_char b '"';
  String.iter
    (fun c ->
      match c with
      | '"' -> Buffer.add_string b "\\\""
      | '\\' -> Buffer.add_string b "\\\\"
      | '\n' -> Buffer.add_string b "\\n"
      | '\t' -> Buffer.add_string b "\\t"
      | '\r' -> Buffer.add_string b "\\r"
      | c when c < ' ' || c = '\x7f' ->
          Printf.bprintf b "\\%03d" (Char.code c)
      | c -> Buffer.add_char b c)
    s;
  Buffer.add_char b '"';
  Buffer.contents b

let () =
  match Array.to_list Sys.argv with
  | [ _; src; dst ] -> (
      let json =
        try Yojson.Basic.from_file src
        with e ->
          die "icon_names_gen: cannot parse %s: %s" src
            (Printexc.to_string e)
      in
      let pairs =
        match json with
        | `List rows ->
            List.map
              (function
                | `List [ `String d; `String k ] -> (d, k)
                | _ -> die "icon_names_gen: bad row in %s" src)
              rows
        | _ -> die "icon_names_gen: %s is not a json array" src
      in
      let oc = open_out_bin dst in
      Printf.fprintf oc "(* generated by tools/icon_names_gen.exe from\n";
      Printf.fprintf oc "   assets/icon-names.json — do not edit *)\n\n";
      Printf.fprintf oc "let items : (string * string) array = [|\n";
      List.iter
        (fun (d, k) -> Printf.fprintf oc "  (%s, %s);\n" (lit d) (lit k))
        pairs;
      Printf.fprintf oc "|]\n";
      close_out oc)
  | _ -> die "usage: icon_names_gen.exe ICON_NAMES_JSON OUT_ML"
